{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — for example, maximizing total profit (with a profit per unit of each component), maximizing total units produced, or meeting a required demand at minimum cost?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the three components produced independently by the workshops (i.e., any workshop can produce any component at its listed rate), or is each component restricted to specific workshops?"
  ],
  "rationale": "The response asks a single clarification question regarding the production constraints of the components across workshops."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any demand limit or upper bound on how many units of each component (or how many finished products) can be produced, or is the only limit the workshops' production capacities?"
  ],
  "rationale": "The response asks a single clarification question regarding whether limits are based on demand or production capacity."
}

{
  "action": "question",
  "question_count": 1,
